struct OperationClass {
    OperationKind kind; ///< What the operation is.
    int order; ///< n of Cn/Sn (1 for identity, inversion, mirrors).
    int power; ///< j: minimal-angle power (see the header comment).
    ClassAxis axis; ///< Axis slot in the canonical orientation.
};

